class Solution {
    int maxSum = 0;
    struct Subtree {
        bool isValid;
        int minVal;
        int maxVal;
        int sum;
    };
    Subtree dfs(TreeNode* node) {
        if (!node) return {true, INT_MAX, INT_MIN, 0};
        Subtree l = dfs(node->left);
        Subtree r = dfs(node->right);
        if (l.isValid && r.isValid && node->val > l.maxVal && node->val < r.minVal) {
            int total = l.sum + r.sum + node->val;
            maxSum = std::max(maxSum, total);
            return {true, std::min(l.minVal, node->val), std::max(r.maxVal, node->val), total};
        }
        return {false, 0, 0, 0};
    }
public:
    int maxSumBST(TreeNode* root) {
        dfs(root);
        return maxSum;
    }
};

class Solution {
    private int maxSum = 0;
    private static class Subtree {
        boolean isValid;
        int minVal, maxVal, sum;
        Subtree(boolean v, int mn, int mx, int s) {
            isValid = v; minVal = mn; maxVal = mx; sum = s;
        }
    }
    private Subtree dfs(TreeNode node) {
        if (node == null) return new Subtree(true, Integer.MAX_VALUE, Integer.MIN_VALUE, 0);
        Subtree l = dfs(node.left);
        Subtree r = dfs(node.right);
        if (l.isValid && r.isValid && node.val > l.maxVal && node.val < r.minVal) {
            int total = l.sum + r.sum + node.val;
            maxSum = Math.max(maxSum, total);
            return new Subtree(true, Math.min(l.minVal, node.val), Math.max(r.maxVal, node.val), total);
        }
        return new Subtree(false, 0, 0, 0);
    }
    public int maxSumBST(TreeNode root) {
        dfs(root);
        return maxSum;
    }
}

var maxSumBST = function(root) {
    let maxSum = 0;
    const dfs = (node) => {
        if (!node) return [true, Infinity, -Infinity, 0];
        const [lValid, lMin, lMax, lSum] = dfs(node.left);
        const [rValid, rMin, rMax, rSum] = dfs(node.right);
        if (lValid && rValid && node.val > lMax && node.val < rMin) {
            const total = lSum + rSum + node.val;
            maxSum = Math.max(maxSum, total);
            return [true, Math.min(lMin, node.val), Math.max(rMax, node.val), total];
        }
        return [false, 0, 0, 0];
    };
    dfs(root);
    return maxSum;
};
